export function parseLine(line) {
  return line.trim();
}

export function parse(text) {
  return text.split('\n').filter(Boolean).map(parseLine);
}

files.names.js:
export function trimName(name) {
  return String(name).trim();
}

export function lowerName(name) {
  return String(name).toLowerCase();
}

export function normalizeName(name) {
  return lowerName(trimName(name));
}

files.names.test.js:
import { trimName, lowerName, normalizeName } from './names.js';

import { describe, it } from 'node:test';
import assert from 'node:assert';

describe('trimName', () => {
  it('trims whitespace', () => {
    assert.strictEqual(trimName('  Alice  '), 'Alice');
  });
});

describe('lowerName', () => {
  it('lower-cases characters', () => {
    assert.strictEqual(lowerName('BOB'), 'bob');
  });
});

describe('normalizeName', () => {
  it('trims and lower-cases', () => {
    assert.strictEqual(normalizeName('  Charlie  '), 'charlie');
  });
});
